#!/usr/bin/env bash
# Guard: the committed catalog tag seed matches a fresh generation from the
# rules docs (database/seeds/0042_catalog_tags.sql, generated by
# app/scripts/generate-tag-seed.ts).
#
# The rules gate runs first, unconditionally blocking: the generator trusts
# only rules files that pass check-game-rules.sh. Override the seed path with
# TAG_SEED_FILE (relative paths resolve from the repo root, as the generator
# does). Generator warnings (a rules file with no tag source) are printed but
# do not fail the run.
#
# Needs app/ dependencies installed (tsx). Runs from any cwd.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

if ! rules_out="$(cd "$ROOT" && env -u GAME_RULES_GATE bash scripts/check-game-rules.sh 2>&1)"; then
  echo "$rules_out" >&2
  echo "check-tag-seeds: FAIL (rules gate must pass before the seed is checked)" >&2
  exit 1
fi

if [ -n "${TAG_SEED_FILE:-}" ]; then
  case "$TAG_SEED_FILE" in
    /*) export TAG_SEED_FILE ;;
    *)  export TAG_SEED_FILE="$ROOT/$TAG_SEED_FILE" ;;
  esac
else
  unset TAG_SEED_FILE
fi

if (cd "$ROOT/app" && npx tsx scripts/generate-tag-seed.ts --check); then
  echo "check-tag-seeds: PASS"
  exit 0
fi

echo "check-tag-seeds: FAIL" >&2
exit 1
